struct sock *clone_lock_sock(const struct sock *sk, const struct request_sock *req, gfp_t priority)
{
    struct sock *new_sk = NULL;

    new_sk = __sock_clone(sk, priority);
    if (!new_sk)
        return NULL;

    sock_lock_init(new_sk);
    new_sk->sk_state = TCP_SYN_RECV;
    new_sk->sk_daddr = req->rmt_addr;
    new_sk->sk_rcv_saddr = req->loc_addr;
    new_sk->sk_bound_dev_if = req->bound_dev_if;
    new_sk->sk_incoming_cpu = -1;
    new_sk->sk_destruct = NULL;

    sock_init_data(NULL, new_sk);
    sk_accept_queue_init(&new_sk->sk_accept_queue);
    security_sock_graft(new_sk, sk->sk_net);
    return new_sk;
}

